#!/usr/bin/env python3
"""Measure build host inputs; runner image labels are provenance, not cache keys.

This is a finite explicit contract for the pinned Linux Chromium toolchain, not
an assertion that arbitrary programs are hermetic. A real cross-runner Siso
zero-action pilot remains mandatory. Full source/output hashes stay separate.
"""
import argparse
import hashlib
import json
import os
from pathlib import Path
import platform
import re
import shutil
import subprocess
import sys


def sha(p):
    h = hashlib.sha256()
    with Path(p).open('rb') as f:
        for b in iter(lambda: f.read(1024**2), b''):
            h.update(b)
    return h.hexdigest()


def run(argv):
    p = subprocess.run(list(map(str, argv)), text=True, capture_output=True,
                       env={**os.environ, 'LC_ALL': 'C.UTF-8', 'LANG': 'C.UTF-8', 'TZ': 'UTC'})
    if p.returncode:
        raise RuntimeError(f'{argv}: exit{p.returncode}: {p.stderr}')
    return p.stdout.strip()


def dependency_paths(output):
    if 'not found' in output:
        raise ValueError('Unresolved dynamic dependency: ' + output)
    paths = set()
    for line in output.splitlines():
        # Both "lib.so => /path (address)" and "/loader (address)".
        m = re.search(r'(?:=>\s+)?(/[^\s]+)(?:\s|$)', line)
        if m:
            paths.add(m[1])
        elif line.strip() and not any(x in line for x in
                ['linux-vdso', 'statically linked', 'not a dynamic executable']):
            raise ValueError('Unrecognized dependency line: ' + line)
    return paths


def main():
    p = argparse.ArgumentParser()
    p.add_argument('--src', type=Path)
    p.add_argument('--out', type=Path)
    p.add_argument('--self-test', action='store_true')
    a = p.parse_args()
    if a.self_test:
        assert dependency_paths('linux-vdso.so.1 (0x00)\nlibm.so.6 => /lib/x/libm.so.6 (0x01)\n/lib64/ld-linux-x86-64.so.2 (0x02)') == {'/lib/x/libm.so.6', '/lib64/ld-linux-x86-64.so.2'}
        try:
            dependency_paths('libbad.so => not found')
        except ValueError:
            pass
        else:
            raise AssertionError('Missing dependency accepted')
        assert dependency_paths('statically linked') == set()
        print('dependency parser controls pass')
        return
    assert sys.platform == 'linux' and platform.machine() == 'x86_64'
    assert a.src and a.out
    src = a.src.resolve()
    tools = {
        'clang': src/'third_party/llvm-build/Release+Asserts/bin/clang',
        'clang++': src/'third_party/llvm-build/Release+Asserts/bin/clang++',
        'ld.lld': src/'third_party/llvm-build/Release+Asserts/bin/ld.lld',
        'llvm-ar': src/'third_party/llvm-build/Release+Asserts/bin/llvm-ar',
        'gn': src/'buildtools/linux64/gn',
        'siso': src/'third_party/siso/cipd/siso',
    }
    # Tools invoked by GN/Python actions outside the hermetic source checkout.
    # Each executable, its loader and transitive shared libraries are hashed.
    for n in ['sh','bash','env','cp','mv','rm','mkdir','ln','touch','cat','chmod',
              'ar','nm','readelf','strip','objcopy','pkg-config','python3','git',
              'tar','gzip','xz','ldd','getconf','sed','grep','find','sort','head','tail','uname']:
        q = shutil.which(n)
        if q is None:
            raise ValueError('Required measured host utility missing: ' + n)
        tools['host:'+n] = Path(q)
    # Ask the actual build python selected by PATH, not this helper's interpreter.
    py = json.loads(run([tools['host:python3'], '-c',
        'import sys,sysconfig,json;print(json.dumps({"executable":sys.executable,"version":sys.version,"cacheTag":sys.implementation.cache_tag,"stdlib":sysconfig.get_path("stdlib"),"platstdlib":sysconfig.get_path("platstdlib"),"prefix":sys.prefix,"basePrefix":sys.base_prefix}))']))
    tools['python:actual'] = Path(py['executable'])
    measured = {}
    pending = list(tools.values())
    # Hash stdlib source and native extensions; ignore generated bytecode and
    # site-packages. Chromium vpython requirements remain pinned source inputs.
    stdlib = {}
    for root in sorted({py['stdlib'], py['platstdlib']}):
        for parent, dirs, files in os.walk(root):
            dirs[:] = sorted(d for d in dirs if d not in {'__pycache__','site-packages','dist-packages'})
            for n in sorted(files):
                f = Path(parent,n)
                if n.endswith(('.pyc','.pyo')) or not f.is_file():
                    continue
                stdlib[str(f)] = {'sha256':sha(f),'resolved':str(f.resolve())}
                if f.suffix == '.so':
                    pending.append(f)
    # ldd already reports transitive deps, but walk all resulting ELF paths too.
    while pending:
        logical = Path(pending.pop())
        real = logical.resolve(strict=True)
        if str(real) in measured:
            continue
        row = {'sha256':sha(real),'size':real.stat().st_size}
        with real.open('rb') as f:
            elf = f.read(4) == b'\x7fELF'
        if elf:
            proc = subprocess.run(['ldd', str(real)], text=True, capture_output=True,
                                  env={**os.environ,'LC_ALL':'C.UTF-8'})
            text = (proc.stdout+'\n'+proc.stderr).strip()
            if proc.returncode and not any(x in text for x in ['statically linked','not a dynamic executable']):
                raise ValueError(f'ldd failed for {real}: {text}')
            deps = sorted(dependency_paths(text))
            row['dynamicDependencies'] = deps
            pending.extend(Path(x) for x in deps)
        measured[str(real)] = row
    versions = {}
    for n, flag in [('clang','--version'),('ld.lld','--version'),('llvm-ar','--version'),('gn','--version'),('siso','version')]:
        versions[n] = run([tools[n],flag])
    versions['python'] = py
    result = {'schema':1,'osRelease':Path('/etc/os-release').read_text(),
              'architecture':platform.machine(),
              'buildEnvironment':{n:os.environ.get(n,'') for n in ['CPATH','C_INCLUDE_PATH','CPLUS_INCLUDE_PATH','LIBRARY_PATH','LD_LIBRARY_PATH','LD_PRELOAD','PYTHONPATH','PYTHONHOME','CC','CXX','AR','LD','CFLAGS','CXXFLAGS','RUSTFLAGS']},
              'locale':{'LANG':'C.UTF-8','LC_ALL':'C.UTF-8','TZ':'UTC'},
              'tools':{n:{'path':str(f),'resolved':str(f.resolve())} for n,f in sorted(tools.items())},
              'versions':versions,'nativeFiles':dict(sorted(measured.items())),
              'pythonStdlibFiles':dict(sorted(stdlib.items()))}
    a.out.write_text(json.dumps(result,sort_keys=True,indent=2))


if __name__ == '__main__':
    main()
